import type { Locator, Page } from "@playwright/test";
import { PNG } from "pngjs";
import type { Page } from "@playwright/test";
import { PI_TARGETS, sourcePresetKeys } from "./pi-manifest.ts";

import { PI_TARGETS, sourcePresetKeys } from "./pi-manifest.ts";
import { PI_PLANT, plantBlackAurora, plantBlankBlob, plantFloodBlob } from "./substrate-paints-color-plants.ts";
import {
    intersectRegion,
    regionArea,
    unclippedRegion,
    grabBlobBaseline,
    forceWebGLFloorPath,
    assertLiveWebGLPath,
    median,
