    // lightness after the OETF, so L^(1/2.2)-ish; a neutral proxy for the luminance witness).
    const g = Math.round(Math.max(0, Math.min(1, Math.pow(Math.max(0, ok.oklabL), 1 / 2.2))) * 255);
