        { t: textSelector, p: plateSelector ?? null, b: backdropSelector ?? null },
    );
    if (!read) return null;
    const lc = apcaLcFromResolved(read.textColor, read.plateColor, read.backdropColor ?? undefined);
    if (lc == null) return null;
    return { lc, ...read };
}

