export function regionStatsDelta(a, b) {
    const dL = (a.meanL ?? 0) - (b.meanL ?? 0);
    const dA = (a.meanA ?? 0) - (b.meanA ?? 0);
    const dB = (a.meanB ?? 0) - (b.meanB ?? 0);
