 */
export function pngRegionDelta(absPath, regionA, regionB) {
    const a = pngRegionStats(absPath, regionA);
    const b = pngRegionStats(absPath, regionB);
    if (!a || !b) return null;
    return { ...regionStatsDelta(a, b), regionA: a, regionB: b };
