        dominantFamily: dom.dominantFamily,
        warm: dom.warm,
        warmFraction: dom.warmFraction,
        coldFraction: dom.coldFraction,
        neutralFraction: dom.neutralFraction,
        angleDegPeak: dom.angleDegPeak,
        meanL: sumL / n,
        meanChroma: sumChroma / n,
        meanA: sumA / n,
        meanB: sumB / n,
        samples: n,
